 	 */
 	public boolean isConnected() {
-		return connected;
+		return connected.get();
 	}

 	public TS3Api getApi() {
@@ -200,19 +218,23 @@ public class TS3Query {
 	}

 	void fireDisconnect() {
-		connected = false;
+		connected.set(false);

 		submitUserTask("ConnectionHandler disconnect task", new Runnable() {
 			@Override
 			public void run() {
-				try {
-					connectionHandler.onDisconnect(TS3Query.this);
-				} finally {
-					if (!connected) {
-						exit();
-					}
-				}
+				handleDisconnect();
 			}
 		});
 	}
+
+	private synchronized void handleDisconnect() {
+		try {
+			connectionHandler.onDisconnect(this);
+		} finally {
+			if (!connected.get()) {
+				shutDown();
+			}
+		}
+	}
 }

**Fix commit date: 2017-11-18**. The BIC must be before this date. Use this as the upper bound for any date-based searches.

